import re
from rapidfuzz import process, fuzz

def limpar(t):
    t = t.lower().strip()
    t = re.sub(r'[^a-z0-9çãáéíóúâêôõü. ]', ' ', t)
    return re.sub(r'\s+', ' ', t).strip()

TIPO_LOGRADOURO = {'r': 'rua', 'r.': 'rua', 'av': 'avenida', 'av.': 'avenida'}
PARTICULAS = {'de', 'da', 'do', 'das', 'dos'}
BAIRROS_REF = ['jardim paulista', 'vila madalena', 'pinheiros', 'moema']

def segmentar_nome(tokens):
    primeiro = tokens[0]
    resto = tokens[1:]
    sobrenome = []
    for tk in resto:
        sobrenome.append(tk)
    return primeiro, ' '.join(sobrenome)

def padronizar_logradouro(tokens):
    if tokens and tokens[0] in TIPO_LOGRADOURO:
        tokens[0] = TIPO_LOGRADOURO[tokens[0]]
    return ' '.join(tokens)

def verificar_bairro(bairro, limiar=80):
    match, score, _ = process.extractOne(bairro, BAIRROS_REF, scorer=fuzz.ratio)
    return match, score < limiar

assert limpar('  Maria   DA Silva  ') == 'maria da silva'
assert padronizar_logradouro(['r.', 'das', 'flores']) == 'rua das flores'
nome, sob = segmentar_nome(limpar('maria da silva neto').split())
assert nome == 'maria' and sob == 'da silva neto'
bairro_corrigido, flag = verificar_bairro('jardim paulsta')
assert bairro_corrigido == 'jardim paulista' and flag is False
_, flag2 = verificar_bairro('bairro inexistente xyz')
assert flag2 is True
print('todos os testes passaram')

