import random, itertools
import jellyfish
from metaphone import doublemetaphone

base = ["Jessica Oliveira","Thiago Souza","Camila Ferreira","Joao Pedro Lima","Larissa Costa"]
regs = []
for cid, nome in enumerate(base):
    for _ in range(random.randint(1,3)):
        n = list(nome)
        if random.random() < 0.5 and len(n) > 3:
            i = random.randrange(len(n)-1)
            n[i], n[i+1] = n[i+1], n[i]
        regs.append({"cluster_id": cid, "nome": "".join(n)})

for r in regs:
    r["sndx"] = jellyfish.soundex(r["nome"])
    r["dmeta"] = doublemetaphone(r["nome"])[0]

def standard_blocking(regs, key):
    blocks = {}
    for idx, r in enumerate(regs):
        blocks.setdefault(r[key], []).append(idx)
    return blocks

def gen_pairs(blocks):
    pairs = set()
    for ids in blocks.values():
        for i, j in itertools.combinations(ids, 2):
            pairs.add((i, j))
    return pairs

for key in ["sndx", "dmeta"]:
    blocks = standard_blocking(regs, key)
    pairs = gen_pairs(blocks)
    true_pairs = {(i, j) for i, j in itertools.combinations(range(len(regs)), 2)
                  if regs[i]["cluster_id"] == regs[j]["cluster_id"]}
    recovered = pairs & true_pairs
    pc = len(recovered) / len(true_pairs) if true_pairs else 0
    print(key, "blocos:", len(blocks), "pares:", len(pairs), "pairs_completeness:", round(pc, 3))

