Em Python, um protótipo simples:

def suffixes(s, lmin):
    return [s[i:] for i in range(len(s)-lmin+1)] if len(s) > lmin else [s]

blocks = {}
for rid, bkv in records.items():
    for suf in suffixes(bkv, lmin=4):
        blocks.setdefault(suf, []).append(rid)
blocks = {k:v for k,v in blocks.items() if len(v) <= bmax}

