import random, itertools, hashlib

def shingles(s, k=2):
    return {s[i:i+k] for i in range(len(s)-k+1)}

def minhash_sig(s, num_hashes=20):
    sh = shingles(s)
    return tuple(min(int(hashlib.md5((str(i)+x).encode()).hexdigest(),16) for x in sh) for i in range(num_hashes))

bases = ["JOAO SILVA","MARIA SOUZA","ANA PEREIRA","CARLOS OLIVEIRA","PAULA SANTOS"]
random.seed(1)
records, true_cluster = [], []
for cid, b in enumerate(bases):
    for _ in range(random.randint(2,4)):
        s = list(b)
        if random.random() < 0.6:
            i = random.randrange(len(s)); s[i] = random.choice("AEIOU")
        records.append("".join(s)); true_cluster.append(cid)

blocks = {}
for idx, name in enumerate(records):
    blocks.setdefault(name[:3], []).append(idx)
std_pairs = {p for v in blocks.values() for p in itertools.combinations(v,2)}

bands, rows = 5, 4
lsh_blocks = {}
for idx, name in enumerate(records):
    sig = minhash_sig(name, bands*rows)
    for band in range(bands):
        key = (band, sig[band*rows:(band+1)*rows])
        lsh_blocks.setdefault(key, []).append(idx)
lsh_pairs = {p for v in lsh_blocks.values() for p in itertools.combinations(v,2)}

true_pairs = {p for p in itertools.combinations(range(len(records)),2) if true_cluster[p[0]]==true_cluster[p[1]]}
print("std:", len(std_pairs), "lsh:", len(lsh_pairs), "true:", len(true_pairs))

