import time
import pandas as pd
from rapidfuzz.distance import Levenshtein

def levenshtein_dp(s1, s2):
    n, m = len(s1), len(s2)
    d = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        d[i][0] = i
    for j in range(m+1):
        d[0][j] = j
    for i in range(1, n+1):
        for j in range(1, m+1):
            if s1[i-1] == s2[j-1]:
                d[i][j] = d[i-1][j-1]
            else:
                d[i][j] = 1 + min(d[i-1][j], d[i][j-1], d[i-1][j-1])
    return d[n][m]

pares = [('gail','gayle'), ('shackleford','shackelford'), ('jones','johnson'),
         ('michelle','michael'), ('nichleson','nichulson')]

for s1, s2 in pares:
    d_meu = levenshtein_dp(s1, s2)
    d_rf = Levenshtein.distance(s1, s2)
    sim = 1.0 - d_meu / max(len(s1), len(s2))
    print(s1, s2, d_meu, d_rf, round(sim, 4))

t0 = time.perf_counter()
for s1, s2 in pares * 400:
    levenshtein_dp(s1, s2)
t1 = time.perf_counter()
for s1, s2 in pares * 400:
    Levenshtein.distance(s1, s2)
t2 = time.perf_counter()
print('python puro:', round(t1-t0, 4), 's | rapidfuzz:', round(t2-t1, 4), 's')

na_pratica:
Em pipelines de deduplicação com Splink ou recordlinkage, q-gram + Jaccard costuma ser usado como feature auxiliar ou regra de bloqueio aproximada, complementando Jaro-Winkler. Em Python puro:

def qgrams(s, q=2):
    return set(s[i:i+q] for i in range(len(s)-q+1))

def jaccard(a, b):
    A, B = qgrams(a), qgrams(b)
    return len(A & B) / len(A | B) if A | B else 0.0

Em SQL/Spark, isso se traduz em explodir os q-grams em arrays e calcular interseção/união via funções de array (array_intersect, array_union) antes de aplicar a fórmula.

Em pipelines de nome completo (ex: cadastro de clientes de um banco ou de um hospital), Monge-Elkan é útil quando você não normalizou a ordem dos tokens (nome do meio, sobrenomes compostos, sufixos como Jr/Filho). Em Python com RapidFuzz você implementa a função secundária com JaroWinkler e faz o loop manualmente, já que não há Monge-Elkan nativo nas libs citadas:

from rapidfuzz.distance import JaroWinkler
def monge_elkan(a_tokens, b_tokens):
    scores = []
    for a in a_tokens:
        best = max(JaroWinkler.similarity(a, b) for b in b_tokens)
        scores.append(best)
    return sum(scores) / len(a_tokens)

No Splink isso normalmente é aproximado usando comparações por token separadas (first_name, middle_name, surname) em vez de uma função Monge-Elkan explícita, já que a lib prioriza comparadores vetorizados em DuckDB/Spark.

