from rapidfuzz.distance import JaroWinkler
import math

pares = [
    ("cia brasileira de bebidas", "companhia brasileira bebidas"),
    ("banco itau sa", "itau unibanco sa"),
    ("magazine luiza ltda", "luiza magazine ltda"),
    ("ambev sa", "companhia de bebidas ambev"),
    ("petrobras distribuidora", "petrobras distrib sa"),
]

def monge_elkan(s1, s2):
    t1, t2 = s1.split(), s2.split()
    soma = sum(max(JaroWinkler.similarity(a, b) for b in t2) for a in t1)
    return soma / len(t1)

corpus_tokens = [tok for par in pares for s in par for tok in s.split()]
n_docs = len(pares) * 2
def idf(token):
    docs_com_token = sum(1 for par in pares for s in par if token in s.split())
    return math.log(n_docs / (1 + docs_com_token))

def tf(token, tokens):
    return tokens.count(token) / len(tokens)

def soft_tfidf(s1, s2, theta=0.9):
    t1, t2 = s1.split(), s2.split()
    total = 0.0
    for a in set(t1):
        sims = [(b, JaroWinkler.similarity(a, b)) for b in set(t2)]
        close = [(b, sim) for b, sim in sims if sim >= theta]
        if not close:
            continue
        n_ab = max(sim for b, sim in close)
        v_a = tf(a, t1) * idf(a)
        v_b = tf(a, t2) * idf(a)
        total += v_a * v_b * n_ab
    return total

for s1, s2 in pares:
    print(f"{s1!r:45} {s2!r:35} ME={monge_elkan(s1,s2):.3f} STFIDF={soft_tfidf(s1,s2):.3f}")

