import math
import pandas as pd
from datetime import date

def sim_num_abs(n1, n2, d_max):
    diff = abs(n1 - n2)
    return max(0.0, 1.0 - diff / d_max) if diff < d_max else 0.0

def sim_day_abs(d1, d2, d_max=30):
    if d1.year == d2.year and d1.day == d2.day and d1.month != d2.month:
        return max(0.75, sim_num_abs((d1-d2).days, 0, d_max))
    if d1.year == d2.year and {d1.day, d1.month} == {d2.day, d2.month} and d1.day <= 12 and d1.month <= 12:
        return 0.5
    diff_days = abs((d1 - d2).days)
    return sim_num_abs(diff_days, 0, d_max)

def haversine_km(lat1, lon1, lat2, lon2):
    R = 6371.0
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlmb = math.radians(lon2 - lon1)
    a = math.sin(dphi/2)2 + math.cos(p1)*math.cos(p2)*math.sin(dlmb/2)2
    return 2 * R * math.asin(math.sqrt(a))

def sim_geo(lat1, lon1, lat2, lon2, d_max_km=5.0):
    dist = haversine_km(lat1, lon1, lat2, lon2)
    return sim_num_abs(dist, 0, d_max_km)

pares = [
    (2000, 2500, date(2010,3,11), date(2010,3,29), -23.5505,-46.6333,-23.5520,-46.6300),
    (5000, 5050, date(2010,1,12), date(2010,7,12), -22.9068,-43.1729,-22.9068,-43.1729),
    (3000, 9000, date(1985,10,12), date(1985,12,10), -15.7801,-47.9292,-3.1190,-60.0217),
]

for n1,n2,d1,d2,lat1,lon1,lat2,lon2 in pares:
    vetor = (round(sim_num_abs(n1,n2,1000),3), round(sim_day_abs(d1,d2),3), round(sim_geo(lat1,lon1,lat2,lon2),3))
    print(vetor)

