import networkx as nx
from recordlinkage.datasets import load_febrl1
from rapidfuzz.distance import JaroWinkler

df = load_febrl1().head(50)
ids = df.index.tolist()
G = nx.Graph()
for i in range(len(ids)):
    for j in range(i+1, len(ids)):
        a, b = df.loc[ids[i]], df.loc[ids[j]]
        s = JaroWinkler.normalized_similarity(str(a.given_name), str(b.given_name))
        s += JaroWinkler.normalized_similarity(str(a.surname), str(b.surname))
        if s >= 1.4:
            G.add_edge(ids[i], ids[j], weight=s)

components = list(nx.connected_components(G))

def center_clustering(graph):
    edges = sorted(graph.edges(data=True), key=lambda e: -e[2]["weight"])
    assigned, clusters = {}, {}
    for u, v, _ in edges:
        if u not in assigned and v not in assigned:
            assigned[u] = u; assigned[v] = u; clusters[u] = {u, v}
        elif u in assigned and v not in assigned:
            c = assigned[u]; clusters[c].add(v); assigned[v] = c
        elif v in assigned and u not in assigned:
            c = assigned[v]; clusters[c].add(u); assigned[u] = c
    return clusters

center_clusters = center_clustering(G)
print("componentes:", len(components), "center:", len(center_clusters))

na_pratica:
Em pipelines de deduplicação que produzem clusters (ex.: saída de linker.clustering.cluster_pairwise_predictions_at_threshold do Splink), avalie contra ground truth usando ambas métricas, nunca só pairwise:

from collections import defaultdict
def bcubed(pred_clusters, true_clusters):
    item_to_pred = {i:c for c in pred_clusters for i in c}
    item_to_true = {i:c for c in true_clusters for i in c}
    precs, recs = [], []
    for i in item_to_pred:
        inter = len(set(item_to_pred[i]) & set(item_to_true[i]))
        precs.append(inter/len(item_to_pred[i]))
        recs.append(inter/len(item_to_true[i]))
    return sum(precs)/len(precs), sum(recs)/len(recs)

Isso ajuda a diagnosticar se o erro dominante é 'poucos clusters gigantes mal formados' (pairwise penaliza mais) versus 'muitos clusters pequenos levemente errados' (BCubed penaliza mais proporcionalmente).

