import hashlib, numpy as np

def qgrams(s, q=2):
    s = f"_{s.lower()}_"
    return {s[i:i+q] for i in range(len(s)-q+1)}

def bloom_filter(qgs, l=500, k=10):
    bf = np.zeros(l, dtype=bool)
    for g in qgs:
        for i in range(k):
            h = int(hashlib.sha256(f"{g}{i}".encode()).hexdigest(), 16)
            bf[h % l] = True
    return bf

def dice_bf(bf1, bf2):
    return 2*np.sum(bf1 & bf2) / (np.sum(bf1) + np.sum(bf2))

def dice_qgrams(q1, q2):
    return 2*len(q1 & q2) / (len(q1) + len(q2))

