import time

def qgrams(s, q=2):
    s = s.lower()
    return {s[i:i+q] for i in range(len(s)-q+1)} if len(s) >= q else {s}

class SimIndex:
    def __init__(self):
        self.inv = defaultdict(set)
        self.records = {}
    def insert(self, rid, name):
        self.records[rid] = name
        for g in qgrams(name):
            self.inv[g].add(rid)
    def query(self, name, topk=5, min_score=0.85):
        cands = set()
        for g in qgrams(name):
            cands |= self.inv.get(g, set())
        scored = [(rid, JaroWinkler.normalized_similarity(name, self.records[rid])) for rid in cands]
        scored = [p for p in scored if p[1] >= min_score]
        return sorted(scored, key=lambda x: -x[1])[:topk]

