def gen_batch(n, seed):
    random.seed(seed)
    pool = ["Ana Silva","Ana Silva","Joao Souza","João Souza","Maria Oliveira","Pedro Lima"]
    return pd.DataFrame({"id": range(n), "name": [random.choice(pool) for _ in range(n)]})

