def link_incremental(batch, registry):
    global total_comparisons
    for _, row in batch.iterrows():
        match = None
        for _, ref in registry.iterrows():
            total_comparisons += 1
            if fuzz.ratio(row["name"], ref["name"]) >= 90:
                match = ref["entity_id"]; break
        eid = match if match else str(uuid.uuid4())[:8]
        registry.loc[len(registry)] = [eid, row["name"]]
    return registry

